        if self.PROVIDER_VERSION is not None:
            PROVIDER_VERSION = builder.CreateString(self.PROVIDER_VERSION)
        if self.PROVIDER_SHA256 is not None:
            PROVIDER_SHA256 = builder.CreateString(self.PROVIDER_SHA256)
        if self.CONFIGURATION is not None:
            CONFIGURATION = self.CONFIGURATION.Pack(builder)
        if self.ATTITUDE is not None:
            ATTITUDE = self.ATTITUDE.Pack(builder)
        if self.AUXILIARY is not None:
            AUXILIARYlist = []
            for i in range(len(self.AUXILIARY)):
                AUXILIARYlist.append(self.AUXILIARY[i].Pack(builder))
            CLGSourceStartAUXILIARYVector(builder, len(self.AUXILIARY))
            for i in reversed(range(len(self.AUXILIARY))):
                builder.PrependUOffsetTRelative(AUXILIARYlist[i])
            AUXILIARY = builder.EndVector()
        if self.INTERPOLATION_ID is not None:
            INTERPOLATION_ID = builder.CreateString(self.INTERPOLATION_ID)
        CLGSourceStart(builder)
        CLGSourceAddCATEGORY(builder, self.CATEGORY)
        if self.RECORD is not None:
            CLGSourceAddRECORD(builder, RECORD)
        if self.THEORY is not None:
            CLGSourceAddTHEORY(builder, THEORY)
        if self.PROVIDER_ID is not None:
            CLGSourceAddPROVIDER_ID(builder, PROVIDER_ID)
        if self.PROVIDER_VERSION is not None:
            CLGSourceAddPROVIDER_VERSION(builder, PROVIDER_VERSION)
        if self.PROVIDER_SHA256 is not None:
            CLGSourceAddPROVIDER_SHA256(builder, PROVIDER_SHA256)
        if self.CONFIGURATION is not None:
            CLGSourceAddCONFIGURATION(builder, CONFIGURATION)
        if self.ATTITUDE is not None:
            CLGSourceAddATTITUDE(builder, ATTITUDE)
        if self.AUXILIARY is not None:
            CLGSourceAddAUXILIARY(builder, AUXILIARY)
        if self.INTERPOLATION_ID is not None:
            CLGSourceAddINTERPOLATION_ID(builder, INTERPOLATION_ID)
        CLGSourceAddPOSITION_ERROR_M(builder, self.POSITION_ERROR_M)
        CLGSourceAddVELOCITY_ERROR_MPS(builder, self.VELOCITY_ERROR_MPS)
        CLGSourceAddACCELERATION_ERROR_MPS2(builder, self.ACCELERATION_ERROR_MPS2)
        CLGSourceAddJERK_ERROR_MPS3(builder, self.JERK_ERROR_MPS3)
        CLGSourceAddATTITUDE_ERROR_RAD(builder, self.ATTITUDE_ERROR_RAD)
        CLGSourceAddANGULAR_RATE_ERROR_RAD_S(builder, self.ANGULAR_RATE_ERROR_RAD_S)
        CLGSourceAddANGULAR_ACCELERATION_ERROR_RAD_S2(builder, self.ANGULAR_ACCELERATION_ERROR_RAD_S2)
        CLGSourceAddHAS_CATEGORY(builder, self.HAS_CATEGORY)
        CLGSourceAddHAS_POSITION_ERROR_M(builder, self.HAS_POSITION_ERROR_M)
        CLGSourceAddHAS_VELOCITY_ERROR_MPS(builder, self.HAS_VELOCITY_ERROR_MPS)
        CLGSourceAddHAS_ACCELERATION_ERROR_MPS2(builder, self.HAS_ACCELERATION_ERROR_MPS2)
        CLGSourceAddHAS_JERK_ERROR_MPS3(builder, self.HAS_JERK_ERROR_MPS3)
        CLGSourceAddHAS_ATTITUDE_ERROR_RAD(builder, self.HAS_ATTITUDE_ERROR_RAD)
        CLGSourceAddHAS_ANGULAR_RATE_ERROR_RAD_S(builder, self.HAS_ANGULAR_RATE_ERROR_RAD_S)
        CLGSourceAddHAS_ANGULAR_ACCELERATION_ERROR_RAD_S2(builder, self.HAS_ANGULAR_ACCELERATION_ERROR_RAD_S2)
        CLGSource = CLGSourceEnd(builder)
        return CLGSource
